// scripts/build-icons.mjs
// Generates src/client/icon-set.js from the v3 icon pack SVGs in src/client/icons/.
// Every class and keyframe is scoped (client/icon-scope.js) so the icons' inline
// <style> blocks can't leak into DSH's CSS. Run via `npm run build:client`, which runs
// this first. The generated file is committed so a plain install needs no build step.
import { readFile, writeFile } from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { scopeIconSvg } from '../src/client/icon-scope.js';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');

// ICONS key → file in src/client/icons/ (the v3 icon pack + switch.svg, 28 icons).
export const ICON_FILES = {
  mic: 'mic-idle',
  micRecording: 'mic-recording',
  processing: 'processing-stt',
  cancelled: 'cancelled',
  play: 'play',
  stop: 'stop',
  generatingTTS: 'generating-tts',
  ttsPlaying: 'tts-playing',
  ttsPaused: 'tts-paused',
  mute: 'mute',
  unmute: 'unmute',
  setDefault: 'set-as-default',
  activeModel: 'active-model',
  checkOk: 'check-ok',
  warning: 'warning',
  recheck: 'recheck',
  download: 'download',
  cancelDownload: 'cancel-download',
  removeModel: 'remove-model',
  refreshCatalogue: 'refresh-catalogue',
  previewPlay: 'preview-play',
  previewStop: 'preview-stop',
  caretDown: 'caret-down',
  caretUp: 'caret-up',
  resetDefault: 'reset-default',
  language: 'language',
  filter: 'filter',
  switch: 'switch',
};

export async function buildIconSet() {
  const out = {};
  for (const [key, file] of Object.entries(ICON_FILES)) {
    const svg = await readFile(path.join(root, 'src', 'client', 'icons', `${file}.svg`), 'utf8');
    out[key] = scopeIconSvg(svg.trim(), key);
  }
  const body =
    `// GENERATED by scripts/build-icons.mjs from src/client/icons/*.svg — do not edit by hand.\n` +
    `export const ICON_SVG = ${JSON.stringify(out, null, 1)};\n`;
  await writeFile(path.join(root, 'src', 'client', 'icon-set.js'), body);
  return Object.keys(out).length;
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const n = await buildIconSet();
  console.log(`built src/client/icon-set.js (${n} icons)`);
}
